parameters.text:
=┌────────────────────────────────────────┐
📋 *NEW POA SUBMISSION: {{ $json.partnerName }}*
├────────────────────────────────────────┤
📄 POA ID: {{ $json.poaId }}
🏷️ Tier: {{ $json.partnerTier }}
📅 Quarter: {{ $json.quarter }}
🎯 Revenue Target: ${{ Number($json.revenueTarget).toLocaleString() }}
💼 Deals Target: {{ $json.dealsTarget }}
💰 MDF Requested: ${{ Number($json.mdfRequested).toLocaleString() }}
├────────────────────────────────────────┤
🎯 Goals: {{ $json.poaGoals.substring(0, 200) }}
├────────────────────────────────────────┤
📌 *Action Needed:* Review within 5 business days.
🔗 Use action="review" with decision="approved" / "needs_revision" / "rejected"
└────────────────────────────────────────┘

=Hi {{ $json.channelManager || 'Channel Manager' }},

A new Plan of Action has been submitted by {{ $json.partnerName }} for {{ $json.quarter }} and requires your review.

---
POA ID: {{ $json.poaId }}
Partner: {{ $json.partnerName }} ({{ $json.partnerTier }})
Quarter: {{ $json.quarter }}
Revenue Target: ${{ Number($json.revenueTarget).toLocaleString() }}
Deals Target: {{ $json.dealsTarget }}
MDF Requested: ${{ Number($json.mdfRequested).toLocaleString() }}

Goals:
{{ $json.poaGoals }}

Key Initiatives:
{{ $json.poaKeyInitiatives || 'Not specified' }}

---
To respond, POST to the webhook with:
{
  "action": "review",
  "partnerId": "{{ $json.partnerId }}",
  "poaId": "{{ $json.poaId }}",
  "reviewDecision": "approved|needs_revision|rejected",
  "reviewComments": "Your feedback here"
}

Please respond within 5 business days.

Best,
Channel Operations
channel@example-channel.com

parameters.responseBody:
={{ {
  success: true,
  message: 'POA submitted successfully. Channel manager notified for review.',
  poaId: $json.poaId,
  partnerName: $json.partnerName,
  quarter: $json.quarter,
  status: 'pending_review',
  nextSteps: 'Awaiting channel manager review (typical: 5 business days)',
  submittedAt: $json.submittedAt
} }}

={{ {
  success: false,
  message: 'POA submission incomplete. Required fields: partnerName, partnerEmail, partnerTier, poaGoals, revenueTarget (>0).',
  poaId: $json.poaId,
  missingFields: [
    $json.partnerName ? null : 'partnerName',
    $json.partnerEmail ? null : 'partnerEmail',
    $json.partnerTier ? null : 'partnerTier',
    $json.poaGoals ? null : 'poaGoals',
    Number($json.revenueTarget) > 0 ? null : 'revenueTarget'
  ].filter(function(f) { return f !== null; }),
  status: 'incomplete'
} }}

={{ {
  success: true,
  message: 'POA approved. Partner notified.',
  poaId: $json.poaId,
  partnerName: $json.partnerName,
  quarter: $json.quarter,
  status: 'approved',
  reviewDecision: 'approved',
  reviewedAt: new Date().toISOString()
} }}

={{ {
  success: true,
  message: 'POA revision requested. Partner notified with feedback.',
  poaId: $json.poaId,
  partnerName: $json.partnerName,
  status: 'needs_revision',
  reviewDecision: 'needs_revision',
  reviewedAt: new Date().toISOString()
} }}

={{ {
  success: true,
  message: 'POA reviewed and not approved. Partner notified with feedback.',
  poaId: $json.poaId,
  partnerName: $json.partnerName,
  status: 'rejected',
  reviewDecision: 'rejected',
  reviewedAt: new Date().toISOString()
} }}

parameters.text:
=┌────────────────────────────────────────┐
⏰ *POA OVERDUE: {{ $json.partnerName }}*
├────────────────────────────────────────┤
📄 POA ID: {{ $json.poaId || 'N/A' }}
📅 Quarter: {{ $json.quarter }}
⏱️ Overdue: {{ $json.body.overdueDays || $json.overdueDays || 'Unknown' }} days
📌 Severity: {{ $json.overdueLevel }}
├────────────────────────────────────────┤
📋 {{ $json.overdueLevel === 'critical' ? '🔴 ESCALATE to Channel Director' : ($json.overdueLevel === 'warning' ? '⚠️ Contact partner this week' : '📧 Send reminder to partner') }}
└────────────────────────────────────────┘

parameters.responseBody:
={{ {
  success: true,
  message: 'Overdue POA reminder sent to partner and CM.',
  poaId: $json.poaId || 'N/A',
  partnerName: $json.partnerName,
  quarter: $json.quarter,
  overdueLevel: $json.overdueLevel,
  status: 'reminder_sent',
  remindedAt: new Date().toISOString()
} }}
